'use strict';

var should = require('chai').should();
var expect = require('chai').expect;
var opcat = require('../..');
var Transaction = opcat.Transaction;

// The package root does not export decodeHex/encodeHex directly; reach the
// modules the way the library itself does.
var decodeHex = require('../../cjs/encoding/decode-hex.cjs');
var encodeHex = require('../../cjs/encoding/encode-hex.cjs');

describe('decodeHex / encodeHex', function () {
  it('uses native Buffer encoding for direct Node imports', function () {
    var bytes = Buffer.from([0xde, 0xad]);
    var nativeToString = bytes.toString;
    var calls = 0;
    bytes.toString = function (encoding) {
      calls += 1;
      return nativeToString.call(this, encoding);
    };

    encodeHex(bytes).should.equal('dead');
    calls.should.equal(1);
  });

  it('round-trips bytes exactly (all 256 values)', function () {
    var bytes = new Uint8Array(256);
    for (var i = 0; i < 256; i++) bytes[i] = i;
    var hex = encodeHex(bytes);
    var back = decodeHex(hex);
    Buffer.from(back).equals(Buffer.from(bytes)).should.equal(true);
  });

  it('matches Buffer.from(hex) on a large payload', function () {
    // The regression this guards: decodeHex previously parsed with
    // parseInt(substr(...)), which is quadratic on JavaScriptCore for
    // concatenation-built strings (24s for 190 KB on iOS). The rewrite must
    // stay byte-identical to the reference decoder.
    var src = Buffer.alloc(65536);
    for (var i = 0; i < src.length; i++) src[i] = (i * 7 + 13) & 0xff;
    var hex = src.toString('hex');
    Buffer.from(decodeHex(hex)).equals(src).should.equal(true);
  });

  it('accepts uppercase and a 0x prefix, pads odd length', function () {
    Buffer.from(decodeHex('0xDEADBEEF')).toString('hex').should.equal('deadbeef');
    Buffer.from(decodeHex('ABC')).toString('hex').should.equal('0abc');
  });

  it('rejects non-hex input instead of guessing', function () {
    // parseInt() would have read 'de ad' as de 0a (it skips whitespace and
    // accepts signs); the strict decoder refuses.
    expect(function () {
      decodeHex('de ad');
    }).to.throw();
    expect(function () {
      decodeHex('zz');
    }).to.throw();
  });

  it('keeps a transaction hex round trip byte-identical through a rope', function () {
    // Build the hex the way a serializer does — by concatenation — so the
    // input is a rope, the exact shape that used to go quadratic.
    var flat =
      '0100000001' +
      '00'.repeat(32) +
      'ffffffff' +
      '0151' +
      'ffffffff' +
      '01' +
      '0100000000000000' +
      '0151' +
      '01aa' +
      '00000000';
    var rope = '';
    for (var i = 0; i < flat.length; i += 8) rope += flat.substr(i, 8);
    var tx = Transaction.fromString(rope);
    tx.uncheckedSerialize().should.equal(flat);
    // clone() is fromString(uncheckedSerialize()) — the original crash site
    tx.clone().uncheckedSerialize().should.equal(flat);
  });
});
